-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (7034, 16, 'Zuschüsse für neue klimafreundliche Heizungen fortführen oder ausbauen', 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'gemischt', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Bundesförderung für effiziente Gebäude, zu der auch die Heizungszuschüsse gehören, ist im Regierungsentwurf 2027 mit rund 12,56 Mrd. Euro im Klima- und Transformationsfonds veranschlagt.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"}]'::jsonb),
  (7035, 16, 'Wärmepumpen-Leasing oder Wärme-Contracting ohne hohe Startinvestition', 'Nimmt Haushalten die hohe Anfangsinvestition ab, die laut KfW oft fehlt; solche Angebote gibt es bisher nur vereinzelt, ihre Wirkung in der Breite ist kaum untersucht.', 'offen', null, 'bund', null, true, null, '[]'::jsonb),
  (7036, 16, 'Heizungsgesetz abschaffen, freie Wahl der Heizung', 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Laut Normenkontrollrat sank der Erfüllungsaufwand um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; entlastet wird überwiegend Aufwand, der noch nicht entstanden war.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ohne die 65-Prozent-Vorgabe wächst laut Öko-Institut die Lücke zum Gebäude-Klimaziel 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Berechnung zu den Eckpunkten, März 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7037, 16, 'Geltende Vorgaben beibehalten, Planungssicherheit bis 2045', 'Vermeidet weitere Wechsel der Regeln; die Vorgaben selbst waren stark umstritten, und ob sie Regierungswechsel überdauern, ist offen – 2026 wurden sie grundlegend geändert.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Der Erfüllungsaufwand sank laut Normenkontrollrat um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; diese Entlastung entfiele bei Beibehaltung der Vorgaben.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Die 65-Prozent-Vorgabe verhindert laut Öko-Institut eine zusätzliche Klimalücke im Gebäudesektor; ihr Wegfall vergrößert die Lücke 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Eckpunkte, 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7038, 16, 'Kommunale Wärmeplanung und Wärmenetze fördern', 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'gemischt', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Wärmeplanung kostet Gemeinden bis ca. 10.000 Einwohner laut Difu mindestens 50.000 Euro; der Bund stellt den Ländern dafür befristet bis 2028 insgesamt 500 Mio. Euro bereit.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7039, 16, 'Modernisierungsumlage für energetische Sanierung abschaffen, Warmmietenneutralität', 'Schützt Mieterinnen und Mieter vor Mietsteigerungen durch den Heizungstausch; zugleich sinkt der Anreiz für Vermieter, die Heizung zu erneuern, sodass Mieter länger die Kosten alter Heizungen tragen können.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb),
  (7158, 16, 'Kommunale Wärmeplanung und Wärmenetze unterstützen: Beratung, Personal, Förderung (Landesprogramm)', 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'gemischt', null, 'land', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7159, 16, 'Kommunale Wärmeplanung vereinfachen, realistische Vorgaben (Landesprogramm)', 'Kann die Planung für kleine Gemeinden beschleunigen; wenn Pläne gröber werden, wissen Eigentümer aber weniger genau, was kommt.', 'offen', null, 'land', null, true, null, '[]'::jsonb),
  (7160, 16, 'Pflicht zur kommunalen Wärmeplanung abschaffen (Landesprogramm)', 'Nimmt Kommunen eine Pflicht ab und Eigentümern das Warten auf einen Plan, schafft aber keine Klarheit, ob ein Wärmenetz kommt. Die Pflicht steht im Bundesrecht; das Land kann nur sein Ausführungsgesetz ändern oder im Bundesrat werben.', 'offen', null, 'land', null, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Kommunen sparen Planungskosten: Das Difu schätzt sie für Orte bis etwa 10.000 Einwohner auf mindestens 50.000 Euro; der Bund gibt den Ländern dafür bis 2028 insgesamt 500 Mio. Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt ist eine vorausschauende kommunale Planung nötig, um Wärmenetze auszubauen und schnell zu dekarbonisieren; der Netzausbau gilt als entscheidend für die Wärmewende.","quelle_url":"https://www.umweltbundesamt.de/themen/waermeversorgung-von-gebaeuden-muss","belegstufe":"A"}]'::jsonb)
