insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (7040, 16, 11, null, 'Heizungsgesetz der Ampel abschaffen, technologieoffene Wärmelösungen', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Laut Normenkontrollrat sank der Erfüllungsaufwand um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; entlastet wird überwiegend Aufwand, der noch nicht entstanden war.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ohne die 65-Prozent-Vorgabe wächst laut Öko-Institut die Lücke zum Gebäude-Klimaziel 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Berechnung zu den Eckpunkten, März 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7041, 16, 11, null, 'Verlässliche, technologieoffene Förderung', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Bundesförderung für effiziente Gebäude, zu der auch die Heizungszuschüsse gehören, ist im Regierungsentwurf 2027 mit rund 12,56 Mrd. Euro im Klima- und Transformationsfonds veranschlagt.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"}]'::jsonb),
  (7042, 16, 12, null, 'Förderung vor allem für die, die sich den Umstieg sonst nicht leisten können', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Bundesförderung für effiziente Gebäude, zu der auch die Heizungszuschüsse gehören, ist im Regierungsentwurf 2027 mit rund 12,56 Mrd. Euro im Klima- und Transformationsfonds veranschlagt.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"}]'::jsonb),
  (7043, 16, 12, null, 'Beschlossene Gesetze umsetzen, Planungssicherheit', '{1602}', 7037, 1, 3, null, 'Vermeidet weitere Wechsel der Regeln; die Vorgaben selbst waren stark umstritten, und ob sie Regierungswechsel überdauern, ist offen – 2026 wurden sie grundlegend geändert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Der Erfüllungsaufwand sank laut Normenkontrollrat um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; diese Entlastung entfiele bei Beibehaltung der Vorgaben.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Die 65-Prozent-Vorgabe verhindert laut Öko-Institut eine zusätzliche Klimalücke im Gebäudesektor; ihr Wegfall vergrößert die Lücke 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Eckpunkte, 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7044, 16, 12, null, 'Lokale Wärmepläne und Kommunen mit Fördermitteln unterstützen', '{1603}', 7038, 2, 2, null, 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Wärmeplanung kostet Gemeinden bis ca. 10.000 Einwohner laut Difu mindestens 50.000 Euro; der Bund stellt den Ländern dafür befristet bis 2028 insgesamt 500 Mio. Euro bereit.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7045, 16, 12, null, 'Soziales Wärmepumpen-Leasing für ärmere Haushalte', '{1601,1604}', 7035, 2, 2, null, 'Nimmt Haushalten die hohe Anfangsinvestition ab, die laut KfW oft fehlt; solche Angebote gibt es bisher nur vereinzelt, ihre Wirkung in der Breite ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (7046, 16, 13, null, 'Gebäudeenergiegesetz beibehalten, Planungssicherheit bis 2045', '{1602}', 7037, 1, 3, null, 'Vermeidet weitere Wechsel der Regeln; die Vorgaben selbst waren stark umstritten, und ob sie Regierungswechsel überdauern, ist offen – 2026 wurden sie grundlegend geändert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Der Erfüllungsaufwand sank laut Normenkontrollrat um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; diese Entlastung entfiele bei Beibehaltung der Vorgaben.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Die 65-Prozent-Vorgabe verhindert laut Öko-Institut eine zusätzliche Klimalücke im Gebäudesektor; ihr Wegfall vergrößert die Lücke 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Eckpunkte, 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7047, 16, 13, null, 'Förderung von bis zu 70 % ausbauen', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Bundesförderung für effiziente Gebäude, zu der auch die Heizungszuschüsse gehören, ist im Regierungsentwurf 2027 mit rund 12,56 Mrd. Euro im Klima- und Transformationsfonds veranschlagt.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"}]'::jsonb),
  (7048, 16, 13, null, 'Wärme-Contracting durch Stadtwerke und Firmen', '{1601}', 7035, 2, 2, null, 'Nimmt Haushalten die hohe Anfangsinvestition ab, die laut KfW oft fehlt; solche Angebote gibt es bisher nur vereinzelt, ihre Wirkung in der Breite ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (7049, 16, 13, null, 'Klimakomponente im Wohngeld stärken', '{1604}', null, 1, 3, null, 'Hilft Haushalten mit Wohngeld, höhere Heizkosten oder Mieten nach einer Sanierung zu tragen; erreicht nur Wohngeldbeziehende und ändert nichts daran, ob die Heizung erneuert wird.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (7050, 16, 14, null, 'Heizungsgesetz vollständig auslaufen lassen, CO₂-Zertifikatehandel statt Einzelvorschriften', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Laut Normenkontrollrat sank der Erfüllungsaufwand um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; entlastet wird überwiegend Aufwand, der noch nicht entstanden war.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ohne die 65-Prozent-Vorgabe wächst laut Öko-Institut die Lücke zum Gebäude-Klimaziel 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Berechnung zu den Eckpunkten, März 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7051, 16, 14, null, 'Kappungsgrenzen bei energetischen Sanierungen lockern', '{1604}', null, 1, 3, null, 'Erhöht den Anreiz für Vermieter, Heizung und Gebäude zu erneuern, was Heizkosten der Mieter senken kann; zugleich dürfen Mieten nach der Sanierung stärker steigen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (7052, 16, 15, null, 'Gebäudeenergiegesetz abschaffen, Verbot von Gas- und Ölheizungen aufheben', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Laut Normenkontrollrat sank der Erfüllungsaufwand um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; entlastet wird überwiegend Aufwand, der noch nicht entstanden war.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ohne die 65-Prozent-Vorgabe wächst laut Öko-Institut die Lücke zum Gebäude-Klimaziel 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Berechnung zu den Eckpunkten, März 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7053, 16, 16, null, 'Heizungstausch nach Einkommen fördern, bis zu 100 % für niedrige Einkommen; 25 Mrd. Euro im Jahr', '{1601}', null, 2, 1, null, 'Beseitigt die Kostenhürde für Haushalte mit kleinem und mittlerem Einkommen weitgehend; 25 Milliarden Euro im Jahr sind ein Vielfaches der heutigen Förderung, die Finanzierung hängt an neuen Steuern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Vorschlag nennt 25 Mrd. Euro im Jahr; im Haushaltsentwurf 2027 sind für die Bundesförderung effiziente Gebäude rund 12,56 Mrd. Euro vorgesehen.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"}]'::jsonb),
  (7054, 16, 16, null, 'Umlage für energetische Sanierung abschaffen, Warmmietenneutralität verankern', '{1604}', 7039, 1, 3, null, 'Schützt Mieterinnen und Mieter vor Mietsteigerungen durch den Heizungstausch; zugleich sinkt der Anreiz für Vermieter, die Heizung zu erneuern, sodass Mieter länger die Kosten alter Heizungen tragen können.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (7055, 16, 16, null, 'Vermieter verpflichten, Fördermittel zu nutzen und weiterzugeben', '{1604}', null, 1, 2, null, 'Kann die Kosten für Mieter senken, wenn saniert wird; eine Pflicht zur Förderung ist ungewöhnlich und schwer durchzusetzen, und sie verpflichtet nicht zur Sanierung selbst.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (7056, 16, 16, null, 'Städte und Gemeinden beim Ausbau von Nah- und Fernwärmenetzen unterstützen', '{1603}', 7038, 2, 2, null, 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=35', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Wärmeplanung kostet Gemeinden bis ca. 10.000 Einwohner laut Difu mindestens 50.000 Euro; der Bund stellt den Ländern dafür befristet bis 2028 insgesamt 500 Mio. Euro bereit.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7057, 16, 17, null, 'Einbau von Wärmepumpen fördern, ohne andere Technologien zu benachteiligen', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Bundesförderung für effiziente Gebäude, zu der auch die Heizungszuschüsse gehören, ist im Regierungsentwurf 2027 mit rund 12,56 Mrd. Euro im Klima- und Transformationsfonds veranschlagt.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"}]'::jsonb),
  (7058, 16, 17, null, 'Heizungsgesetz sofort abschaffen und durch sinnvolle Regelungen ersetzen', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Laut Normenkontrollrat sank der Erfüllungsaufwand um rund 6,8 Mrd. Euro, zum Großteil durch das Gebäudemodernisierungsgesetz; entlastet wird überwiegend Aufwand, der noch nicht entstanden war.","quelle_url":"https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Pressemitteilungen/DE/2026/2026-10-nkr-jahresbericht-2026.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ohne die 65-Prozent-Vorgabe wächst laut Öko-Institut die Lücke zum Gebäude-Klimaziel 2030 um 5 bis 8 auf 30 bis 33 Mio. t CO₂e pro Jahr (Berechnung zu den Eckpunkten, März 2026).","quelle_url":"https://idw-online.de/de/news866964","belegstufe":"C","zweite_quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1191030"}]'::jsonb),
  (7059, 16, 17, null, 'Ausbau der Fernwärme unterstützen', '{1603}', 7038, 2, 2, null, 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=12', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Wärmeplanung kostet Gemeinden bis ca. 10.000 Einwohner laut Difu mindestens 50.000 Euro; der Bund stellt den Ländern dafür befristet bis 2028 insgesamt 500 Mio. Euro bereit.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7161, 16, 11, 'ST', 'Kommunale Wärmeplanung realistisch und bezahlbar gestalten', '{1603}', 7159, 1, 3, null, 'Kann die Planung für kleine Gemeinden beschleunigen; wenn Pläne gröber werden, wissen Eigentümer aber weniger genau, was kommt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=46', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (7162, 16, 12, 'ST', 'Kommunen fachlich und finanziell bei der Wärmeplanung unterstützen', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=24', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7163, 16, 13, 'ST', 'Kommunen und Heizungsbesitzer bei der Wärmewende und Wärmeplanung stärker unterstützen', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=25', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7164, 16, 14, 'ST', 'Kommunen sollen Nahwärmenetze aufbauen können, auch mit Kooperationen oder Konzessionen', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7165, 16, 15, 'ST', 'Landesgesetz zur Wärmeplanung abschaffen, im Bundesrat für Abschaffung des Wärmeplanungsgesetzes', '{1603}', 7160, 1, 1, null, 'Nimmt Kommunen eine Pflicht ab und Eigentümern das Warten auf einen Plan, schafft aber keine Klarheit, ob ein Wärmenetz kommt. Die Pflicht steht im Bundesrecht; das Land kann nur sein Ausführungsgesetz ändern oder im Bundesrat werben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=158', null, 'offen', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Kommunen sparen Planungskosten: Das Difu schätzt sie für Orte bis etwa 10.000 Einwohner auf mindestens 50.000 Euro; der Bund gibt den Ländern dafür bis 2028 insgesamt 500 Mio. Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt ist eine vorausschauende kommunale Planung nötig, um Wärmenetze auszubauen und schnell zu dekarbonisieren; der Netzausbau gilt als entscheidend für die Wärmewende.","quelle_url":"https://www.umweltbundesamt.de/themen/waermeversorgung-von-gebaeuden-muss","belegstufe":"A"}]'::jsonb),
  (7166, 16, 16, 'ST', 'Kommunale Wärmeplanung fachlich und finanziell unterstützen, Wärmenetze auch auf dem Land fördern', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=108', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7167, 16, 17, 'ST', 'Kommunale Wärmeplanung flexibel und praxisnah gestalten', '{1603}', 7159, 1, 3, null, 'Kann die Planung für kleine Gemeinden beschleunigen; wenn Pläne gröber werden, wissen Eigentümer aber weniger genau, was kommt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=34', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (7168, 16, 12, 'MV', 'Stadtwerke als zentrale Akteure der Wärmeplanung sichern und unterstützen', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=17', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7169, 16, 13, 'MV', 'Kommunen umfassend bei Wärmeplanung und Umsetzung unterstützen, Beratung ausbauen', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://gruene-mv.de/?wpdmdl=33772#page=8', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7170, 16, 14, 'MV', 'Verpflichtende kommunale Wärmeplanung abschaffen, Freiwilligkeit', '{1603}', 7160, 1, 1, null, 'Nimmt Kommunen eine Pflicht ab und Eigentümern das Warten auf einen Plan, schafft aber keine Klarheit, ob ein Wärmenetz kommt. Die Pflicht steht im Bundesrecht; das Land kann nur sein Ausführungsgesetz ändern oder im Bundesrat werben.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=65', null, 'offen', '2026-09-30', false, true, null, '[{"bereich":"aufwand","richtung":"vorteil","text":"Kommunen sparen Planungskosten: Das Difu schätzt sie für Orte bis etwa 10.000 Einwohner auf mindestens 50.000 Euro; der Bund gibt den Ländern dafür bis 2028 insgesamt 500 Mio. Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt ist eine vorausschauende kommunale Planung nötig, um Wärmenetze auszubauen und schnell zu dekarbonisieren; der Netzausbau gilt als entscheidend für die Wärmewende.","quelle_url":"https://www.umweltbundesamt.de/themen/waermeversorgung-von-gebaeuden-muss","belegstufe":"A"}]'::jsonb),
  (7171, 16, 14, 'MV', 'Bürgschaftsprogramm für kleine Wärmenetze', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=65', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7172, 16, 15, 'MV', 'Tiefengeothermie als kommunale Wärmequelle fördern, Genehmigungen entbürokratisieren', '{1603}', null, 1, 2, null, 'Kann dort, wo die Geologie passt, Wärmenetze möglich machen und so Klarheit über die künftige Versorgung schaffen; Tiefengeothermie ist teuer, braucht Jahre und kommt nur für einen Teil der Gemeinden in Frage.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=86', null, 'offen', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Für das Bundesprogramm KfW-Förderkredit Geothermie (Bohrungen für Wärmenetze) stellt der Bund einen Garantierahmen von 600 Mio. Euro und rund 50 Mio. Euro Haushaltsmittel bereit.","quelle_url":"https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Deutschlandfonds.html","belegstufe":"A"},{"bereich":"umwelt","richtung":"gemischt","text":"Laut Umweltbundesamt vermeidet Geothermie Treibhausgase und birgt bei Einhaltung der Vorgaben keine unbeherrschbaren Umweltrisiken; induzierte Seismizität gehört zu den geprüften Risiken.","quelle_url":"https://www.umweltbundesamt.de/themen/klima-energie/erneuerbare-energien/geothermie","belegstufe":"A"}]'::jsonb),
  (7173, 16, 11, 'BE', 'Kommunale Wärmeplanung als Orientierung fortführen, Fernwärme dekarbonisieren', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7174, 16, 12, 'BE', 'Fernwärme über die Wärmeplanung ausbauen, Förderdarlehen für neue Wärmenetze', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=59', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7175, 16, 13, 'BE', 'Wärmewende-Manager in den Bezirken, Förderinstrumente für die Umsetzung der Wärmeplanung', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=13', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7176, 16, 14, 'BE', 'Fern- und Nahwärmenetze im Stadtgebiet ausweiten', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=87', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7177, 16, 16, 'BE', 'Wärmeagentur, Beratung und Förderung, mehr Personal für die Bezirke', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=195', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7178, 16, 17, 'BE', 'Konsequenter Ausbau der Fernwärme, gesteuert über die kommunale Wärmeplanung', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=46', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Bund stellt den Ländern für die erstmalige Wärmeplanung bis 2028 insgesamt 500 Mio. Euro bereit; das Difu schätzt die Kosten je Gemeinde bis etwa 10.000 Einwohner auf mindestens 50.000 Euro.","quelle_url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/kwp/kwp.html","belegstufe":"A"}]'::jsonb),
  (7227, 16, 11, null, 'Investitionen in Klimatechnologien und Energieeffizienz steuerlich schneller absetzbar, auch für Vermieter', '{1604}', null, 1, 2, null, 'Macht den Heizungstausch auch für Vermieter steuerlich attraktiver, sodass mehr Mietwohnungen umgestellt werden können; ob Mieterinnen und Mieter dabei sparen, hängt von der Umlage ab, und die Maßnahme ist nicht auf Mietwohnungen zugeschnitten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'offen', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Alle Maßnahmen des Investitionssofortprogramms zusammen (u. a. Abschreibungen, Körperschaftsteuer) senken die Steuern 2026 um 8,1 und 2027 um 11,8 Mrd. Euro.","quelle_url":"https://www.bundestag.de/dokumente/textarchiv/2025/kw23-de-investitionssofortprogramm-1083898","belegstufe":"A"}]'::jsonb);

